import { yipayUrl, verifyYipayNotify } from './pay';

type Bindings = { DB: D1Database };

const STAGES = [2, 7, 15, 30]; // days after creation for each review cycle
const STAGE_KEYS = ['第2日', '第7日', '第15日', '第30日'];

const app = new Hono<{ Bindings: Bindings }>();

// ---------- helpers ----------
function today(): string {
  return new Date().toISOString().slice(0, 10);
}
function nextDue(stage: number): string {
  const d = new Date();
  d.setDate(d.getDate() + STAGES[stage]);
  return d.toISOString().slice(0, 10);
}

