app.get('/api/today', async (c) => {
  const uid = c.get('uid') as number;
  const t = today();
  const { results } = await c.env.DB.prepare(
    'SELECT id, word, pos, meaning, stage FROM words WHERE user_id=? AND done=0 AND next_due <= ? ORDER BY next_due'
  ).bind(uid, t).all();
  const { results: addedRows } = await c.env.DB.prepare(
    "SELECT COUNT(*) AS n FROM words WHERE user_id=? AND date(created_at) = ?"
  ).bind(uid, t).all<{ n: number }>();
  const addedToday = addedRows[0]?.n ?? 0;
  return c.json({ date: t, count: results.length, added_today: addedToday, words: results });
});

// Monday-based week start for a given date
function weekStart(d: Date): string {
  const x = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dow = (x.getUTCDay() + 6) % 7; // Mon=0
  x.setUTCDate(x.getUTCDate() - dow);
  return x.toISOString().slice(0, 10);
}

app.get('/api/words', async (c) => {
  const uid = c.get('uid') as number;
  const filter = c.req.query('filter') || 'cur'; // cur | last | last2 | more | all
  let where = 'user_id=? AND done=0';
  const binds: (string | number)[] = [uid];
  if (filter === 'cur' || filter === 'last' || filter === 'last2' || filter === 'more') {
    const now = new Date();
    const monday = new Date(weekStart(now)); // current week's Monday
    if (filter === 'cur') { where += ' AND date(created_at) >= ?'; binds.push(monday.toISOString().slice(0, 10)); }
    if (filter === 'last') {
      where += ' AND date(created_at) >= ? AND date(created_at) < ?';
      const lw = new Date(monday); lw.setUTCDate(lw.getUTCDate() - 7);
      binds.push(lw.toISOString().slice(0, 10), monday.toISOString().slice(0, 10));
    }
    if (filter === 'last2') {
      where += ' AND date(created_at) >= ? AND date(created_at) < ?';
      const lw = new Date(monday); lw.setUTCDate(lw.getUTCDate() - 7);
      const lw2 = new Date(monday); lw2.setUTCDate(lw2.getUTCDate() - 14);
      binds.push(lw2.toISOString().slice(0, 10), lw.toISOString().slice(0, 10));
    }
    if (filter === 'more') {
      where += ' AND date(created_at) < ?';
      const lw2 = new Date(monday); lw2.setUTCDate(lw2.getUTCDate() - 14);
      binds.push(lw2.toISOString().slice(0, 10));
    }
  }
  const { results } = await c.env.DB.prepare(
    `SELECT id, word, pos, meaning, stage, next_due, created_at FROM words WHERE ${where} ORDER BY created_at DESC, id DESC`
  ).bind(...binds).all();
  // pagination: default page size 10; page_size=all returns everything (used by random player)
  const total = results.length;
  if (c.req.query('page_size') === 'all') {
    return c.json({ words: results, stages: STAGE_KEYS, total });
  }
  const pageSize = 10;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  let page = Number(c.req.query('page') || 1);
  if (!Number.isFinite(page) || page < 1) page = 1;
  if (page > totalPages) page = totalPages;
  const start = (page - 1) * pageSize;
  return c.json({ words: results.slice(start, start + pageSize), stages: STAGE_KEYS, page, totalPages, total });
});

app.post('/api/words', async (c) => {
  const uid = c.get('uid') as number;
  // member-only: adding words requires an active membership
  const u = await c.env.DB.prepare('SELECT membership_expires_at FROM users WHERE id=?').bind(uid).first<{ membership_expires_at: string | null }>();
  const isMember = !!u?.membership_expires_at && new Date(u.membership_expires_at.replace(' ', 'T') + 'Z') > new Date();
  if (!isMember) return c.json({ error: '添加新词为会员专享功能，请先开通会员', code: 'MEMBER_REQUIRED' }, 403);
  const body = await c.req.json<{ word?: string; pos?: string; meaning?: string }>();
  const word = (body.word || '').trim();
  const meaning = (body.meaning || '').trim();
  if (!word || !meaning) return c.json({ error: '单词和中文翻译必填' }, 400);
  const pos = (body.pos || '').trim();
  await c.env.DB.prepare('INSERT INTO words (word, pos, meaning, user_id) VALUES (?, ?, ?, ?)').bind(word, pos, meaning, uid).run();
  return c.json({ ok: true });
});

app.delete('/api/words/:id', async (c) => {
  const uid = c.get('uid') as number;
  await c.env.DB.prepare('DELETE FROM words WHERE id = ? AND user_id = ?').bind(Number(c.req.param('id')), uid).run();
  return c.json({ ok: true });
});

// submit dictation: id, correct
app.post('/api/review', async (c) => {
  const uid = c.get('uid') as number;
  const body = await c.req.json<{ id: number; correct: boolean }>();
  const id = Number(body.id);
  const row = await c.env.DB.prepare('SELECT stage FROM words WHERE id=? AND user_id=? AND done=0').bind(id, uid).first<{ stage: number }>();
  if (!row) return c.json({ error: '单词不存在或已完成' }, 404);
  if (body.correct) {
    if (row.stage >= STAGES.length - 1) {
      // last cycle (第30日) passed -> done, filtered out of library
      await c.env.DB.prepare("UPDATE words SET done=1, stage=? WHERE id=?").bind(STAGES.length, id).run();
      return c.json({ ok: true, result: 'done', message: '🎉 恭喜！30日记忆周期全部完成，转入长期记忆！' });
    }
    const ns = row.stage + 1;
    await c.env.DB.prepare('UPDATE words SET stage=?, next_due=? WHERE id=?').bind(ns, nextDue(ns), id).run();
    return c.json({ ok: true, result: 'next', message: `✅ 正确！下次复习：${STAGE_KEYS[ns]}` });
  } else {
    // wrong: restart cycle from 第2日
    await c.env.DB.prepare("UPDATE words SET stage=0, next_due=date('now','+2 day') WHERE id=?").bind(id).run();
    return c.json({ ok: true, result: 'restart', message: '❌ 默写错误，复习周期已重置（2天后重新开始）' });
  }
});

