// ---------- USER SYSTEM ----------
const CHAN_MAP: Record<string, string> = { alipay: 'alipay', wechat: 'wxpay', usdt: 'usdt', stripe: 'fiatstripe' };

app.post('/api/auth/register', async (c) => {
  const b = await c.req.json<{ email?: string; password?: string; nickname?: string }>();
  const email = (b.email || '').trim().toLowerCase();
  const password = b.password || '';
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return jsonErr('邮箱格式不正确');
  if (password.length < 6) return jsonErr('密码至少6位');
  const exist = await c.env.DB.prepare('SELECT id FROM users WHERE email=?').bind(email).first();
  if (exist) return jsonErr('该邮箱已注册');
  const { hash, salt } = await makePassword(password);
  const nickname = (b.nickname || email.split('@')[0]).slice(0, 30);
  const r = await c.env.DB.prepare('INSERT INTO users (email, password_hash, salt, nickname) VALUES (?,?,?,?)')
    .bind(email, hash, salt, nickname).run();
  const uid = r.meta.last_row_id as number;
  // trial: new users get a 30-day membership automatically
  await extendMembership(c.env, uid, 30);
  const token = randToken();
  await c.env.DB.prepare("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, datetime('now','+30 day'))")
    .bind(token, uid).run();
  const res = c.json({ ok: true, trial: '30天会员试用已自动开通' });
  res.headers.append('Set-Cookie', sessionCookie('wb_session', token));
  return res;
});

app.post('/api/auth/login', async (c) => {
  const b = await c.req.json<{ email?: string; password?: string }>();
  const email = (b.email || '').trim().toLowerCase();
  const u = await c.env.DB.prepare('SELECT * FROM users WHERE email=?').bind(email).first<Row>();
  if (!u) return jsonErr('邮箱或密码错误', 401);
  const h = await hashPassword(b.password || '', u.salt);
  if (h !== u.password_hash) return jsonErr('邮箱或密码错误', 401);
  const token = randToken();
  await c.env.DB.prepare("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, datetime('now','+30 day'))")
    .bind(token, u.id).run();
  const res = c.json({ ok: true });
  res.headers.append('Set-Cookie', sessionCookie('wb_session', token));
  return res;
});

app.post('/api/auth/logout', (c) => {
  const res = c.json({ ok: true });
  res.headers.append('Set-Cookie', clearCookie('wb_session'));
  return res;
});

