// create order -> returns payment redirect
app.post('/api/orders', async (c) => {
  const u = await currentUser(c.env, c.req.raw);
  if (!u) return jsonErr('请先登录', 401);
  const b = await c.req.json<{ plan_id?: number; channel?: string }>();
  const plan = await c.env.DB.prepare('SELECT * FROM plans WHERE id=? AND active=1').bind(Number(b.plan_id)).first<Row>();
  if (!plan) return jsonErr('会员项不存在');
  const channel = String(b.channel || '');
  if (!['usdt', 'wechat', 'alipay', 'stripe'].includes(channel)) return jsonErr('请选择支付方式');
  const s = await getSettings(c.env);
  const orderNo = 'WB' + Date.now() + Math.floor(Math.random() * 1000);
  await c.env.DB.prepare("INSERT INTO orders (order_no, user_id, plan_id, plan_name, amount_usd, channel) VALUES (?,?,?,?,?,?)")
    .bind(orderNo, u.id, plan.id, plan.name, plan.price_usd, channel).run();
  await c.env.DB.prepare("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v")
    .bind('od:' + orderNo, String(plan.period_days)).run();
  const site = new URL(c.req.url).origin;

  // all channels (usdt/wechat/alipay/stripe) go through the yipay gateway
  if (!s.yipay_apiurl || !s.yipay_pid || !s.yipay_key) return jsonErr('管理员未配置易支付网关');
  const url = yipayUrl(
    { apiurl: s.yipay_apiurl, pid: s.yipay_pid, key: s.yipay_key, channel: CHAN_MAP[channel] || channel },
    orderNo, `会员-${plan.name}`, plan.price_usd, `${site}/pay/notify`, `${site}/pay/return?order=${orderNo}`, site
  );
  return c.json({ ok: true, redirect: url });
});

// yipay async notify (GET or POST)
async function handleYipayNotify(c: any): Promise<Response> {
  const params: Record<string, string> = {};
  // gateway may call back via GET query OR POST form — merge both
  for (const [k, v] of Object.entries(c.req.query())) params[k] = String(v);
  if (c.req.method === 'POST') {
    try {
      const body = await c.req.parseBody();
      for (const [k, v] of Object.entries(body)) {
        if (typeof v === 'string') params[k] = v;
      }
    } catch {}
  }
  const s = await getSettings(c.env);
  if (!s.yipay_key || !verifyYipayNotify(params, s.yipay_key)) return c.text('sign error');
  if (params.trade_status !== 'TRADE_SUCCESS') return c.text('not success');
  await fulfillOrder(c.env, params.out_trade_no, params.trade_no || '');
  return c.text('success');
}
app.get('/pay/notify', handleYipayNotify);
app.post('/pay/notify', handleYipayNotify);

// stripe return: user lands back after gateway payment; just route to membership page
app.get('/pay/return', async (c) => {
  const orderNo = c.req.query('order') || '';
  const o = orderNo ? await c.env.DB.prepare('SELECT status FROM orders WHERE order_no=?').bind(orderNo).first<Row>() : null;
  return c.redirect(o?.status === 'paid' ? '/membership?paid=1' : '/membership?pending=1');
});

async function fulfillOrder(env: { DB: D1Database }, orderNo: string, tradeNo: string): Promise<void> {
  const o = await env.DB.prepare("SELECT * FROM orders WHERE order_no=? AND status!='paid'").bind(orderNo).first<Row>();
  if (!o) return;
  const pd = await env.DB.prepare('SELECT v FROM settings WHERE k=?').bind('od:' + orderNo).first<Row>();
  await env.DB.prepare("UPDATE orders SET status='paid', paid_at=datetime('now'), trade_no=? WHERE id=?").bind(tradeNo, o.id).run();
  await extendMembership(env, o.user_id, Number(pd?.v || 0));
}

// my orders
app.get('/api/my/orders', async (c) => {
  const u = await currentUser(c.env, c.req.raw);
  if (!u) return jsonErr('请先登录', 401);
  const { results } = await c.env.DB.prepare('SELECT order_no, plan_name, amount_usd, channel, status, created_at, paid_at FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 50').bind(u.id).all();
  // pending orders: show at most 5 by default
  const pending = results.filter((o: any) => o.status !== 'paid');
  const paid = results.filter((o: any) => o.status === 'paid');
  return c.json({ orders: [...pending.slice(0, 5), ...paid], pending_truncated: pending.length > 5, pending_total: pending.length });
});

// ---- user password change: two ways ----
// way 1: email verification code
app.post('/api/auth/sendcode', async (c) => {
  const b = await c.req.json<{ email?: string }>();
  const email = (b.email || '').trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return jsonErr('邮箱格式不正确');
  const u = await c.env.DB.prepare('SELECT id FROM users WHERE email=?').bind(email).first();
  if (!u) return jsonErr('该邮箱未注册', 404);
  const s = await getSettings(c.env);
  if (!s.smtp_host || !s.smtp_user || !s.smtp_pass) return jsonErr('邮箱服务未配置，请联系管理员', 503);
  // rate limit: 1 per minute per email (stored in settings as code:email entries with timestamp)
  const prev = await c.env.DB.prepare("SELECT v FROM settings WHERE k=?").bind('pwcode_ts:' + email).first<{ v: string }>();
  if (prev?.v && Date.now() - Number(prev.v) < 60_000) return jsonErr('发送太频繁，请1分钟后再试');
  const code = String(Math.floor(100000 + Math.random() * 900000));
  await c.env.DB.prepare("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v")
    .bind('pwcode:' + email, code).run();
  await c.env.DB.prepare("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v")
    .bind('pwcode_ts:' + email, String(Date.now())).run();
  try {
    await sendMail({ host: s.smtp_host, port: Number(s.smtp_port || 465), user: s.smtp_user, pass: s.smtp_pass, from: s.smtp_from },
      email, 'WordBook 密码修改验证码',
      `<p>您的密码修改验证码是：<b style="font-size:20px">${code}</b>，10分钟内有效。如非本人操作请忽略本邮件。</p>`);
  } catch (e: any) {
    return jsonErr('验证码发送失败: ' + e.message, 502);
  }
  return c.json({ ok: true });
});

app.post('/api/auth/resetpw', async (c) => {
  const b = await c.req.json<{ email?: string; code?: string; next?: string }>();
  const email = (b.email || '').trim().toLowerCase();
  const code = (b.code || '').trim();
  const next = b.next || '';
  if (next.length < 6) return jsonErr('新密码至少6位');
  const row = await c.env.DB.prepare("SELECT v FROM settings WHERE k=?").bind('pwcode:' + email).first<{ v: string }>();
  const ts = await c.env.DB.prepare("SELECT v FROM settings WHERE k=?").bind('pwcode_ts:' + email).first<{ v: string }>();
  if (!row?.v || !ts?.v) return jsonErr('请先获取验证码');
  if (Date.now() - Number(ts.v) > 10 * 60_000) return jsonErr('验证码已过期，请重新获取');
  if (row.v !== code) return jsonErr('验证码错误');
  const u = await c.env.DB.prepare('SELECT id FROM users WHERE email=?').bind(email).first<{ id: number }>();
  if (!u) return jsonErr('该邮箱未注册', 404);
  const { hash, salt } = await makePassword(next);
  await c.env.DB.prepare('UPDATE users SET password_hash=?, salt=? WHERE id=?').bind(hash, salt, u.id).run();
  // invalidate all sessions of this user
  await c.env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(u.id).run();
  const res = c.json({ ok: true, message: '密码已修改，请重新登录' });
  res.headers.append('Set-Cookie', clearCookie('wb_session'));
  return res;
});

// way 2: current password
app.post('/api/auth/changepw', async (c) => {
  const u = await currentUser(c.env, c.req.raw);
  if (!u) return jsonErr('请先登录', 401);
  const b = await c.req.json<{ current?: string; next?: string }>();
  const h = await hashPassword(b.current || '', u.salt);
  if (h !== u.password_hash) return jsonErr('当前密码错误', 401);
  const next = b.next || '';
  if (next.length < 6) return jsonErr('新密码至少6位');
  const { hash, salt } = await makePassword(next);
  await c.env.DB.prepare('UPDATE users SET password_hash=?, salt=? WHERE id=?').bind(hash, salt, u.id).run();
  return c.json({ ok: true, message: '密码已修改' });
});

// ---------- ADMIN ----------
function adminCookieName() { return 'wb_admin'; }
async function adminAuth(c: any): Promise<boolean> {
  const token = getCookie(c.req.raw, adminCookieName());
  if (!token) return false;
  const s = await getSettings(c.env);
  return token === 'ok:' + (s.admin_password || '') && !!s.admin_password;
}

app.post('/api/admin/login', async (c) => {
  const b = await c.req.json<{ password?: string }>();
  const s = await getSettings(c.env);
  if (!s.admin_password) return jsonErr('后台未初始化：请先通过 wrangler 设置 ADMIN_PASSWORD 或访问初始化接口', 503);
  if ((b.password || '') !== s.admin_password) return jsonErr('密码错误', 401);
  const res = c.json({ ok: true });
  res.headers.append('Set-Cookie', sessionCookie(adminCookieName(), 'ok:' + s.admin_password, 1));
  return res;
});
// change admin password (requires current password) — defined after adminGuard below
app.post('/api/admin/logout', (c) => {
  const res = c.json({ ok: true });
  res.headers.append('Set-Cookie', clearCookie(adminCookieName()));
  return res;
});

// change admin password (requires current password) — defined after adminGuard below

const adminGuard = async (c: any, next: any) => {
  if (!(await adminAuth(c))) return jsonErr('未登录', 401);
  await next();
};

app.post('/api/admin/password', adminGuard, async (c) => {
  const b = await c.req.json<{ current?: string; next?: string }>();
  const s = await getSettings(c.env);
  if ((b.current || '') !== s.admin_password) return jsonErr('当前密码错误', 401);
  const next = (b.next || '').trim();
  if (next.length < 8) return jsonErr('新密码至少8位');
  await setSetting(c.env, 'admin_password', next);
  // re-issue admin session with new password
  const res = c.json({ ok: true });
  res.headers.append('Set-Cookie', sessionCookie(adminCookieName(), 'ok:' + next, 1));
  return res;
});

app.get('/api/admin/settings', adminGuard, async (c) => {
  const s = await getSettings(c.env);
  const mask = (v: string) => v ? (v.length > 6 ? v.slice(0, 3) + '***' + v.slice(-3) : '***') : '';
  return c.json({
    smtp: { host: s.smtp_host || '', port: s.smtp_port || '', user: s.smtp_user || '', from: s.smtp_from || '', pass: mask(s.smtp_pass || '') },
    yipay: { apiurl: s.yipay_apiurl || '', pid: s.yipay_pid || '', key: mask(s.yipay_key || '') },
    pay_channels: JSON.parse(s.pay_channels || '["usdt","wechat","alipay","stripe"]'),
  });
});

app.post('/api/admin/settings', adminGuard, async (c) => {
  const b = await c.req.json<Row>();
  const map: [string, string][] = [
    ['smtp_host', b.smtp_host], ['smtp_port', b.smtp_port], ['smtp_user', b.smtp_user], ['smtp_from', b.smtp_from],
    ['yipay_apiurl', b.yipay_apiurl], ['yipay_pid', b.yipay_pid],
  ];
  for (const [k, v] of map) if (v != null) await setSetting(c.env, k, String(v).trim());
  // secrets: only overwrite when non-empty & not masked
  if (b.smtp_pass && !b.smtp_pass.includes('***')) await setSetting(c.env, 'smtp_pass', b.smtp_pass);
  if (b.yipay_key && !b.yipay_key.includes('***')) await setSetting(c.env, 'yipay_key', b.yipay_key);
  if (Array.isArray(b.pay_channels)) await setSetting(c.env, 'pay_channels', JSON.stringify(b.pay_channels));
  return c.json({ ok: true });
});

app.post('/api/admin/test-mail', adminGuard, async (c) => {
  const b = await c.req.json<{ to?: string }>();
  const s = await getSettings(c.env);
  if (!s.smtp_host || !s.smtp_user || !s.smtp_pass) return jsonErr('请先保存 SMTP 配置');
  try {
    await sendMail({ host: s.smtp_host, port: Number(s.smtp_port || 465), user: s.smtp_user, pass: s.smtp_pass, from: s.smtp_from },
      (b.to || s.smtp_user).trim(), 'WordBook SMTP 测试邮件',
      '<p>这是一封测试邮件，收到即说明 SMTP 配置成功。</p>');
    return c.json({ ok: true });
  } catch (e: any) {
    return jsonErr('发送失败: ' + e.message, 502);
  }
});

// admin users
app.get('/api/admin/users', adminGuard, async (c) => {
  const q = (c.req.query('q') || '').trim();
  let sql = `SELECT id, email, nickname, membership_expires_at, created_at FROM users`;
  const binds: string[] = [];
  if (q) {
    sql += ` WHERE email LIKE ? OR nickname LIKE ? OR CAST(id AS TEXT) = ?`;
    const like = `%${q}%`;
    binds.push(like, like, q);
  }
  sql += ` ORDER BY id DESC LIMIT 200`;
  const { results } = await c.env.DB.prepare(sql).bind(...binds).all();
  return c.json({ users: results });
});
app.put('/api/admin/users/:id/membership', adminGuard, async (c) => {
  const id = Number(c.req.param('id'));
  const v = (c.req.query('expires') || '').trim(); // '' to clear, 'YYYY-MM-DD HH:MM:SS'
  if (v && !/^\d{4}-\d{2}-\d{2}( \d{2}:\d{2}:\d{2})?$/.test(v)) return jsonErr('日期格式: YYYY-MM-DD');
  const val = v ? (v.length === 10 ? v + ' 00:00:00' : v) : null;
  await c.env.DB.prepare('UPDATE users SET membership_expires_at=? WHERE id=?').bind(val, id).run();
  return c.json({ ok: true });
});
app.delete('/api/admin/users/:id', adminGuard, async (c) => {
  const id = Number(c.req.param('id'));
  await c.env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(id).run();
  await c.env.DB.prepare('DELETE FROM users WHERE id=?').bind(id).run();
  return c.json({ ok: true });
});

// admin plans
app.get('/api/admin/plans', adminGuard, async (c) => {
  const { results } = await c.env.DB.prepare('SELECT * FROM plans ORDER BY sort, price_usd').all();
  return c.json({ plans: results });
});
app.post('/api/admin/plans', adminGuard, async (c) => {
  const b = await c.req.json<Row>();
  const name = (b.name || '').trim();
  const days = Number(b.period_days), price = Number(b.price_usd);
  if (!name || !(days > 0) || !(price >= 0)) return jsonErr('名称/周期天数/价格必填');
  const r = await c.env.DB.prepare('INSERT INTO plans (name, period_days, price_usd, active, sort) VALUES (?,?,?,?,?)')
    .bind(name, days, price, b.active === false ? 0 : 1, Number(b.sort || 0)).run();
  return c.json({ ok: true, id: r.meta.last_row_id });
});
app.put('/api/admin/plans/:id', adminGuard, async (c) => {
  const id = Number(c.req.param('id'));
  const b = await c.req.json<Row>();
  const sets: string[] = []; const binds: any[] = [];
  if (b.name != null) { sets.push('name=?'); binds.push(String(b.name).trim()); }
  if (b.period_days != null) { sets.push('period_days=?'); binds.push(Number(b.period_days)); }
  if (b.price_usd != null) { sets.push('price_usd=?'); binds.push(Number(b.price_usd)); }
  if (b.active != null) { sets.push('active=?'); binds.push(b.active ? 1 : 0); }
  if (b.sort != null) { sets.push('sort=?'); binds.push(Number(b.sort)); }
  if (sets.length) await c.env.DB.prepare(`UPDATE plans SET ${sets.join(', ')} WHERE id=?`).bind(...binds, id).run();
  return c.json({ ok: true });
});
app.delete('/api/admin/plans/:id', adminGuard, async (c) => {
  await c.env.DB.prepare('DELETE FROM plans WHERE id=?').bind(Number(c.req.param('id'))).run();
  return c.json({ ok: true });
});

// admin orders
app.get('/api/admin/orders', adminGuard, async (c) => {
  const { results } = await c.env.DB.prepare(
    `SELECT o.order_no, o.plan_name, o.amount_usd, o.channel, o.status, o.trade_no, o.created_at, o.paid_at, u.email
     FROM orders o LEFT JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 200`
  ).all();
  return c.json({ orders: results });
});

// ---------- PWA ----------
const ICON_192_B64 = "";
const ICON_512_B64 = "";
function pngResponse(b64: string): Response {
  const bytes = Uint8Array.from(atob(b64), (ch) => ch.charCodeAt(0));
  return new Response(bytes, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400' } });
}
app.get('/icon-192.png', () => pngResponse(ICON_192_B64));
app.get('/icon-512.png', () => pngResponse(ICON_512_B64));
app.get('/manifest.webmanifest', (c) => c.json({
  name: '科学背单词',
  short_name: '背单词',
  description: '基于艾宾浩斯遗忘曲线的科学背单词应用',
  start_url: '/',
  display: 'standalone',
  background_color: '#f0f4f8',
  theme_color: '#4f46e5',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
}));
app.get('/sw.js', (c) => new Response(`const CACHE='wb-v2';
self.addEventListener('install', (e) => { self.skipWaiting(); });
self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET') return;
  const url = new URL(e.request.url);
  if (url.origin !== location.origin) return;
  if (url.pathname.startsWith('/api/')) return;
  const isIcon = url.pathname.startsWith('/icon-');
  const isNav = e.request.mode === 'navigate' || url.pathname === '/';
  if (!isIcon && !isNav) return;
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    if (isIcon) {
      const cached = await cache.match(e.request);
      if (cached) return cached;
    }
    try {
      const res = await fetch(e.request);
      if (res.ok && (isIcon || isNav)) cache.put(e.request, res.clone());
      return res;
    } catch (err) {
      const cached = await cache.match(e.request);
      if (cached) return cached;
      throw err;
    }
  })());
});`, { headers: { 'Content-Type': 'application/javascript', 'Cache-Control': 'no-cache' } }));

